const $=s=>document.querySelector(s);
const roles={student:['学员端','MEMBER','◉','让每一次训练，\n都值得期待。','从找到合适的课程，到看清每一节课时。把注意力留给训练。'],coach:['教练端','COACH','✳','专注教学，\n日程井然有序。','可约时间、授课名单和课后确认，在一个工作台完成。'],admin:['管理端','MANAGER','▦','一家门店，\n经营一目了然。','排课、人员与课时账各有归属，每一次调整都有记录。']};
const menus={student:[['home','⌂','首页'],['classes','▦','约课'],['bookings','◷','预约'],['wallet','◈','课包'],['messages','☷','消息']],coach:[['home','⌂','工作台'],['schedule','▦','课表'],['availability','◷','可约时间'],['messages','☷','消息']],admin:[['home','⌂','总览'],['schedule','▦','排课'],['members','♙','人员'],['finance','◈','课时账'],['messages','☷','消息']]};
const initial=()=>({packages:{private:{available:10,frozen:0,used:2},group:{available:8,frozen:0,used:4}},courses:[{id:'core',name:'核心力量',type:'group',coach:'林教练',date:'2026-10-28',time:'18:30',end:'19:30',room:'A 团操室',capacity:10,occupied:6,icon:'力',tone:''},{id:'yoga',name:'流动瑜伽',type:'group',coach:'苏教练',date:'2026-10-28',time:'19:45',end:'20:45',room:'B 瑜伽室',capacity:8,occupied:7,icon:'柔',tone:'warm'},{id:'hiit',name:'HIIT 燃脂',type:'group',coach:'林教练',date:'2026-10-29',time:'18:30',end:'19:30',room:'A 团操室',capacity:8,occupied:8,icon:'燃',tone:'blue'}],bookings:[],ledger:[{title:'购买私教课包',detail:'线下转账 · 管理员入账',value:'+12 节'},{title:'私教到课消耗',detail:'历史训练记录',value:'−2 节'},{title:'购买团课课包',detail:'线下转账 · 管理员入账',value:'+12 节'},{title:'团课到课消耗',detail:'历史训练记录',value:'−4 节'}],messages:[{title:'欢迎加入元素领域',text:'你的私教和团课课包已准备好，开始预约下一次训练吧。'}],revenue:5280,availability:['09:00','10:30','14:00','15:30'],people:[{name:'陈晓',phone:'138****0628',type:'学员',status:'正常'},{name:'林教练',phone:'139****2156',type:'教练',status:'正常'},{name:'苏教练',phone:'137****9021',type:'教练',status:'正常'},{name:'周然',phone:'136****3805',type:'学员',status:'待审核'}]});
let state;try{state=JSON.parse(localStorage.getItem('yuanli-prototype-v1'))||initial()}catch{state=initial()}
let role='student',page='home',classType='private',date='2026-10-28',bookingFilter='active',coachFilter='all';
const weekDates=['2026-10-28','2026-10-29','2026-10-30','2026-10-31','2026-11-01','2026-11-02','2026-11-03'];
const weekNames=['周三','周四','周五','周六','周日','周一','周二'];
function daySlots(day=date){if(!state.weekAvailability)state.weekAvailability=Object.fromEntries(weekDates.map(d=>[d,[...state.availability]]));return state.weekAvailability[day]||[]}
function dateLabel(day){return Number(day.slice(5,7))+' 月 '+Number(day.slice(8))+' 日'}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const save=()=>{try{localStorage.setItem('yuanli-prototype-v1',JSON.stringify(state))}catch{}};
const total=k=>state.packages.private[k]+state.packages.group[k];
const label=t=>t==='private'?'私教':'团课';
const active=b=>b.status==='active';
const notify=(title,text)=>state.messages.unshift({title,text});
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function go(p){page=p;render();$('#screen').scrollTop=0}
function setRole(r){role=r;page='home';render()}
function modal(title,html){$('#modal').innerHTML=`<section class="sheet" role="dialog" aria-modal="true" aria-label="${title}"><div class="row"><h2>${title}</h2><button class="close" onclick="closeModal()" aria-label="关闭">×</button></div>${html}</section>`;$('#modal').hidden=false;$('#modal').querySelector('.close').focus()}
function closeModal(){$('#modal').hidden=true}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&!$('#modal').hidden){const nodes=[...$('#modal').querySelectorAll('button,input,select')];const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
$('#reset').onclick=()=>modal('重置体验',`<p class="sub">清除本原型中的演示预约和课时变更，恢复初始数据。</p><button class="bigbutton" onclick="state=initial();save();closeModal();render();toast('演示数据已重置')">确认重置</button>`);
function render(){
 $('#roles').innerHTML=Object.entries(roles).map(([k,v])=>`<button class="role ${role===k?'active':''}" onclick="setRole('${k}')"><em>${v[2]}</em><span><b>${v[0]}</b><small>${v[1]}</small></span></button>`).join('');
 $('#roleTitle').textContent=roles[role][0]+' · 页面体验';$('#contextTitle').innerHTML=roles[role][3].replace('\n','<br>');$('#contextText').textContent=roles[role][4];
 $('#tabs').innerHTML=menus[role].map(([k,i,n])=>`<button class="${page===k?'active':''}" onclick="go('${k}')"><i>${i}</i>${n}</button>`).join('');
 const views={home:home,classes:classes,bookings:bookings,wallet:wallet,messages:messages,schedule:schedule,availability:availability,members:members,finance:finance};$('#screen').innerHTML=views[page]();
}
const heading=(title,action='')=>`<div class="section-title"><h3>${title}</h3>${action}</div>`;
const balance=()=>`<div class="balance"><div><b>${total('available')}</b><small>可用课时</small></div><div><b>${total('frozen')}</b><small>预约冻结</small></div><div><b>${total('used')}</b><small>已完成课时</small></div></div>`;
const datebar=()=>`<div class="dates week-dates">${weekDates.map((d,i)=>`<button aria-label="${dateLabel(d)} ${weekNames[i]}" aria-pressed="${date===d}" class="${date===d?'active':''}" onclick="date='${d}';render()">${weekNames[i]}<strong>${Number(d.slice(8))}</strong><small>${Number(d.slice(5,7))}月</small></button>`).join('')}</div>`;
function courseCard(c){let booked=state.bookings.some(b=>b.courseId===c.id&&b.status!=='cancelled'),full=c.occupied>=c.capacity;return `<article class="card course"><div class="tile ${c.tone||''}">${esc(c.icon||'课')}</div><div class="info"><div class="row"><h3>${esc(c.name)}</h3><span class="tag">${label(c.type)}</span></div><div class="meta">${esc(c.coach)} · ${esc(c.room)}<br>${c.date.slice(5)}　${c.time}–${c.end}</div><div class="row"><span class="meta">${full?'已满员':`还剩 ${c.capacity-c.occupied} 个名额`} · 1 节</span><button class="pill" ${full||booked?'disabled':''} onclick="bookDialog('${c.id}')">${booked?'已预约':full?'已满员':'预约'}</button></div></div></article>`}
function home(){if(role==='student')return `<div class="greet"><div><small>10 月 27 日，星期二</small><h2>陈晓，动起来。</h2></div><div class="avatar">晓</div></div><div class="hero"><span class="tag">YOUR NEXT CHAPTER</span><h2>把好状态，<br>练成日常。</h2><p>每一次到场，都是向前一步 ↗</p><div class="hero-art"></div></div>${balance()}<div class="booking-entry"><button onclick="classType='private';go('classes')"><b>预约私教 ↗</b><small>按教练排班选日期、选时段</small></button><button onclick="classType='group';go('classes')"><b>预约团课 ↗</b><small>按已发布场次选择开课时间</small></button></div>${heading('下一次训练',`<button class="link" onclick="go('bookings')">全部预约 →</button>`)}${state.bookings.filter(active).slice(0,1).map(bookingCard).join('')||'<div class="notice">下一次训练，由你决定。选一节喜欢的课程吧。</div>'}${heading('为你推荐',`<button class="link" onclick="go('classes')">查看课表 →</button>`)}${state.courses.filter(c=>!c.cancelled).slice(0,2).map(courseCard).join('')}`;
 if(role==='coach')return `<div class="greet"><div><small>COACH WORKSPACE</small><h2>林教练，准备开练。</h2></div><div class="avatar">林</div></div><div class="hero"><span class="tag">保持节奏 · 专注教学</span><h2>每一份进步，<br>都有你的陪伴。</h2><div class="hero-art"></div></div><div class="stats"><div class="card"><small>待结课预约</small><b>${state.bookings.filter(b=>active(b)&&b.coach==='林教练').length}</b><small>逐位确认出勤</small></div><div class="card"><small>已完成 · 演示新增</small><b>${state.bookings.filter(b=>b.status==='done'&&b.coach==='林教练').length}</b><small>课时已结算</small></div></div><div class="actions"><button onclick="go('schedule')"><i>▦</i>授课名单</button><button onclick="go('availability')"><i>◷</i>可约时间</button><button onclick="go('messages')"><i>☷</i>课表通知</button></div>${heading('待结课')}${state.bookings.filter(b=>active(b)&&b.coach==='林教练').map(coachCard).join('')||'<div class="empty">暂时没有待结课预约<br>可先在学员端预约核心力量。</div>'}`;
 return `<div class="greet"><div><small>元素领域 Ez Element · 城市中心店</small><h2>门店经营，一目了然。</h2></div><div class="avatar">管</div></div><div class="hero"><span class="tag">STORE OVERVIEW</span><h2>让热爱有序发生。</h2><p>单店运营 / 线下收款 / 全流程课时账</p><div class="hero-art"></div></div><div class="stats"><div class="card"><small>线下入账 · 演示累计</small><b>¥${state.revenue.toLocaleString()}</b><small>收款与消课分开统计</small></div><div class="card"><small>有效预约 · 陈晓</small><b>${state.bookings.filter(active).length}</b><small>课时冻结 ${total('frozen')} 节</small></div></div><div class="actions"><button onclick="scheduleDialog()"><i>＋</i>新增团课</button><button onclick="purchaseDialog()"><i>◈</i>购课入账</button><button onclick="go('members')"><i>♙</i>人员管理</button></div>${heading('运营待办')}<div class="card"><div class="row"><span>待审核学员</span><button class="pill secondary" onclick="go('members')">${state.people.filter(p=>p.status==='待审核').length} 人 →</button></div></div><div class="notice">试运营建议：每日核对未结课预约与课时流水，避免漏记。</div>`;
}
function slotEnd(t){return String(Number(t.slice(0,2))+1).padStart(2,'0')+t.slice(2)}
function slotReason(t){const end=slotEnd(t);if(state.bookings.some(b=>b.status!=='cancelled'&&b.date===date&&b.time<end&&b.end>t))return '与你的预约冲突';if(state.courses.some(c=>!c.cancelled&&c.coach==='林教练'&&c.date===date&&c.time<end&&c.end>t))return '教练已有课程';return ''}
function groupSessionCard(c){const booked=state.bookings.some(b=>b.courseId===c.id&&b.status!=='cancelled'),full=c.occupied>=c.capacity;return `<article class="card session-card"><div class="row session-time"><strong>${c.time}<span>–${c.end}</span></strong><span class="tag ${full?'orange':''}">${full?'已满员':`余 ${c.capacity-c.occupied} 位`}</span></div><h3>${esc(c.name)}</h3><p class="meta">${esc(c.coach)} · ${esc(c.room)} · 团课 1 节</p><button class="bigbutton ${booked||full?'light':''}" ${booked||full?'disabled':''} onclick="bookDialog('${c.id}')">${booked?'已预约此场次':full?'场次已满':'预约 '+c.time+' 场次'}</button></article>`}
function classes(){const group=classType==='group',list=state.courses.filter(c=>c.date===date&&!c.cancelled).sort((a,b)=>a.time.localeCompare(b.time));return `<h2 class="pagehead">选个时间，开始训练</h2><div class="segments"><button class="${group?'active':''}" onclick="classType='group';render()">多人团课</button><button class="${!group?'active':''}" onclick="classType='private';render()">一对一私教</button></div><div class="booking-step"><b>01</b><span>选择日期</span><small>10/28 — 11/03</small></div>${datebar()}<div class="booking-step"><b>02</b><span>${group?'选择开课场次':'选择私教时段'}</span><small>${dateLabel(date)}</small></div>${group?(list.map(groupSessionCard).join('')||'<div class="empty">当天暂无团课排期<br>请选择其他日期查看场次。</div>'):`<div class="coach-inline"><div class="avatar">林</div><div><strong>林教练 · 当天开放 ${daySlots().length} 个时段</strong><small>与教练排班同步 · 每节 60 分钟</small></div></div><div class="inline-slots">${daySlots().map(t=>{const reason=slotReason(t);return `<button ${reason?'disabled':''} onclick="bookPrivate('${t}')"><strong>${t}–${slotEnd(t)}</strong><small>${reason||'可预约 · 1 节'}</small></button>`}).join('')||'<div class="empty">教练暂未开放时段，请联系门店。</div>'}</div><p class="sub">选择一个可约时段，下一步确认预约。</p><div class="notice">预约冻结 1 节私教课时，到课后扣除。建议至少提前 12 小时取消。</div>`}`}
function bookDialog(id){let c=state.courses.find(x=>x.id===id);modal('确认预约',`<p class="sub">给自己安排一次高质量训练。</p><div class="card"><h3>${esc(c.name)}</h3><p class="meta">${c.date}　${c.time}–${c.end}<br>${esc(c.coach)} · ${esc(c.room)}</p></div><div class="bill row"><span>使用课包</span><b>团课 12 次卡</b></div><div class="bill row"><span>本次冻结</span><b>1 节</b></div><div class="bill row"><span>当前可用</span><b>${state.packages.group.available} 节</b></div><div class="notice">开课前 2 小时可自助取消并释放课时。上课确认后才正式消耗。</div><button class="bigbutton" onclick="confirmBook('${id}')">确认预约 · 冻结 1 节</button>`)}
function privateDialog(){modal('选择私教时段',`<p class="sub">${date} · 林教练 · 60 分钟</p><div class="slots">${daySlots().map(t=>`<button onclick="bookPrivate('${t}')">${t}</button>`).join('')}</div><div class="notice">点击时段进入确认。已被预约或与团课重叠的时间会提示不可预约。</div>`)}
function bookPrivate(t){const end=String(Number(t.slice(0,2))+1).padStart(2,'0')+t.slice(2);modal('确认私教预约',`<div class="card"><h3>专属力量训练</h3><p class="meta">${date}　${t}–${end}<br>林教练 · 私教区</p></div><p class="sub">使用私教课包，当前可用 ${state.packages.private.available} 节。预约冻结 1 节，到课后扣除。</p><button class="bigbutton" onclick="confirmBook(null,'${t}','${end}')">确认预约</button>`)}
function conflict(c){return state.bookings.some(b=>active(b)&&b.date===c.date&&b.time<c.end&&b.end>c.time)}
function confirmBook(id,t,end){if(!id&&!daySlots().includes(t))return toast('该时段已关闭，请重新选择');let c=id?state.courses.find(x=>x.id===id):{id:'private-'+date+'-'+t,name:'专属力量训练',type:'private',coach:'林教练',date,time:t,end,room:'私教区'};if(id&&(c.cancelled||c.occupied>=c.capacity))return toast('该场次已不可预约');if(conflict(c))return toast('与已有预约时间冲突，请选择其他时段');if(!id&&state.courses.some(x=>!x.cancelled&&x.coach===c.coach&&x.date===c.date&&x.time<c.end&&x.end>c.time))return toast('教练在这个时间有团课，请换个时段');let p=state.packages[c.type];if(p.available<1)return toast('课包余额不足，请联系门店');p.available--;p.frozen++;if(id)c.occupied++;state.bookings.unshift({...c,id:'booking-'+Date.now(),courseId:c.id,status:'active'});state.ledger.unshift({title:c.name+' · 预约冻结',detail:c.date+' '+c.time,value:'可用 −1 / 冻结 +1'});notify('预约成功',`${c.name} · ${c.date} ${c.time}，已冻结 1 节课时。`);save();closeModal();go('bookings');toast('预约成功，已冻结 1 节课时')}
function bookingCard(b){const status={active:'待上课',done:'已完成',cancelled:'已取消'};return `<div class="card timecard"><div class="row"><span class="time">${b.time}</span><span class="tag ${b.status==='cancelled'?'orange':''}">${status[b.status]}</span></div><h3 style="font-size:14px">${esc(b.name)}</h3><div class="meta">${b.date} · ${esc(b.coach)} · ${esc(b.room)}</div><div class="row"><span class="meta">${label(b.type)}课包 · ${active(b)?'冻结':'处理'} 1 节</span>${active(b)?`<button class="smallbutton" onclick="cancelDialog('${b.id}')">取消预约</button>`:''}</div></div>`}
function bookings(){let list=state.bookings.filter(b=>bookingFilter==='active'?active(b):!active(b));return `<h2 class="pagehead">我的预约</h2><div class="segments"><button class="${bookingFilter==='active'?'active':''}" onclick="bookingFilter='active';render()">待上课</button><button class="${bookingFilter==='history'?'active':''}" onclick="bookingFilter='history';render()">历史记录</button></div>${list.map(bookingCard).join('')||'<div class="empty">这里还没有预约记录<br><button class="pill" onclick="go(\'classes\')">去选一节课 →</button></div>'}`}
function cancelDialog(id){let b=state.bookings.find(x=>x.id===id);modal('取消这次预约？',`<p class="sub">${esc(b.name)} · ${b.date} ${b.time}</p><div class="notice">本演示预约均按可免费取消处理。取消后释放 1 节${label(b.type)}课时，并通知教练。</div><button class="bigbutton" onclick="cancelBooking('${id}')">确认取消 · 释放课时</button><button class="bigbutton light" onclick="closeModal()">保留预约</button>`)}
function release(b){if(!active(b))return;let p=state.packages[b.type];p.frozen--;p.available++;b.status='cancelled';let c=state.courses.find(x=>x.id===b.courseId);if(c)c.occupied--;state.ledger.unshift({title:b.name+' · 取消释放',detail:'预约取消，返回原课包',value:'可用 +1 / 冻结 −1'})}
function cancelBooking(id){let b=state.bookings.find(x=>x.id===id);release(b);notify('预约已取消',`${b.name}的冻结课时已释放。`);save();closeModal();render();toast('已取消，课时已释放')}
function wallet(){return `<h2 class="pagehead">每一节，都有记录</h2><p class="sub">课包独立使用，余额清楚明白。</p>${['private','group'].map(t=>{let p=state.packages[t];return `<div class="pack ${t}"><div class="row"><h3>${label(t)} 12 次卡</h3><span>↗</span></div><div class="metrics"><div><strong>${p.available}</strong><small>可用课时</small></div><div><strong>${p.frozen}</strong><small>已冻结</small></div><div><strong>${p.used}</strong><small>已消耗</small></div></div><footer>有效期至 2027.04.27 · ${t==='private'?'适用林教练':'适用店内团课'}</footer></div>`}).join('')}${heading('最近课时流水')}${ledger()}`}
function ledger(){return state.ledger.map(l=>`<div class="ledger"><span>${esc(l.title)}<small>${esc(l.detail)}</small></span><b>${esc(l.value)}</b></div>`).join('')}
function coachCard(b){return `<div class="card"><div class="row"><b>${esc(b.name)}</b><span class="tag">待结课</span></div><p class="meta">${b.date} ${b.time} · 陈晓 · ${label(b.type)}</p><button class="bigbutton" onclick="finishDialog('${b.id}')">确认到课并消课</button></div>`}
function finishDialog(id){modal('确认学员已到课',`<p class="sub">陈晓 · 本次将冻结的 1 节课时转为已消耗。</p><div class="notice">原型允许提前演示结课；正式版在课后操作并保留出勤记录。</div><button class="bigbutton" onclick="finishBooking('${id}')">确认到课 · 消耗 1 节</button>`)}
function finishBooking(id){let b=state.bookings.find(x=>x.id===id);if(!active(b))return toast('该预约已经处理');b.status='done';let p=state.packages[b.type];p.frozen--;p.used++;state.ledger.unshift({title:b.name+' · 到课消耗',detail:'林教练确认到课',value:'冻结 −1 / 消耗 +1'});notify('本次训练已完成',`${b.name}消耗 1 节课时，继续保持训练节奏。`);save();closeModal();render();toast('结课成功，课时已结算')}
function schedule(){let cs=state.courses.filter(c=>c.date===date&&(role==='admin'||c.coach==='林教练'));return `<div class="row"><h2 class="pagehead">${role==='admin'?'门店课表':'我的课表'}</h2>${role==='admin'?'<button class="pill" onclick="scheduleDialog()">＋ 排课</button>':''}</div>${datebar()}${cs.map(c=>`<div class="card"><div class="row"><b>${c.time}–${c.end}</b><span class="tag ${c.cancelled?'orange':''}">${c.cancelled?'已停课':`${c.occupied}/${c.capacity} 人`}</span></div><h3>${esc(c.name)}</h3><p class="meta">${esc(c.coach)} · ${esc(c.room)}</p><div class="row"><button class="pill secondary" onclick="roster('${c.id}')">查看名单</button>${role==='admin'&&!c.cancelled?`<button class="smallbutton" onclick="stopDialog('${c.id}')">取消场次</button>`:''}</div></div>`).join('')}${state.bookings.filter(b=>b.date===date&&b.type==='private'&&active(b)).map(role==='coach'?coachCard:bookingCard).join('')}${cs.length===0?'<p class="sub">当天暂无团课排期。</p>':''}`}
function roster(id){let c=state.courses.find(x=>x.id===id),bs=state.bookings.filter(b=>b.courseId===id&&b.status!=='cancelled');modal(c.name+' · 学员名单',`<p class="sub">${c.date} ${c.time} · 已占 ${c.occupied} / ${c.capacity}</p>${bs.map(b=>`<div class="card member"><div class="avatar">晓</div><div class="text"><b>陈晓</b><small>${b.status==='done'?'已到课 · 已消课':'已预约 · 待到课'}</small></div>${active(b)?`<button class="pill" onclick="finishDialog('${b.id}')">结课</button>`:''}</div>`).join('')}<div class="notice">初始名额包含背景演示学员；本轮操作仅展示陈晓的可交互记录。</div>`)}
function coachSlotBusy(t){const end=slotEnd(t);return state.bookings.some(b=>active(b)&&b.coach==='林教练'&&b.date===date&&b.time<end&&b.end>t)||state.courses.some(c=>!c.cancelled&&c.coach==='林教练'&&c.date===date&&c.time<end&&c.end>t)}
function availability(){const slots=daySlots();return `<h2 class="pagehead">一周可约排班</h2><p class="sub">10 月 28 日 — 11 月 3 日 · 每天独立设置</p>${datebar()}<div class="row"><h3>${dateLabel(date)}</h3><span class="tag">开放 ${slots.length} 个时段</span></div><div class="row"><button class="pill secondary" onclick="copyWeekDialog()">复制到其他日期</button><button class="smallbutton" onclick="restDayDialog()">当天停止新预约</button></div><div class="notice">开关即时保存，只修改选中日期。已有预约保留；与团课或私教重叠的时间不能新开放。</div>${['09:00','10:30','14:00','15:30','17:00','18:30','20:00'].map(t=>{const on=slots.includes(t),busy=coachSlotBusy(t);return `<div class="card row"><div><b>${t}–${slotEnd(t)}</b><div class="meta">${busy?'已有课程占用':'私教 · 60 分钟'}</div></div><button aria-label="${t} ${on?'关闭':'开放'}时段" class="pill ${on?'':'secondary'}" ${!on&&busy?'disabled':''} onclick="toggleSlot('${t}')">${on?'已开放 ✓':busy?'不可开放':'已关闭'}</button></div>`}).join('')}`}
function toggleSlot(t){const slots=daySlots();if(!slots.includes(t)&&coachSlotBusy(t))return toast('该时段已有课程');state.weekAvailability[date]=slots.includes(t)?slots.filter(x=>x!==t):[...slots,t].sort();save();render();toast(dateLabel(date)+'排班已保存')}
function restDayDialog(){modal('停止当天新预约',`<p class="sub">${dateLabel(date)} 的所有私教开放时段将关闭，其他日期不变。已有预约仍保留。</p><button class="bigbutton" onclick="daySlots();state.weekAvailability[date]=[];save();closeModal();render();toast('当天已停止新预约')">确认关闭当天时段</button>`)}
function copyWeekDialog(){modal('复制当天排班',`<p class="sub">将 ${dateLabel(date)} 的 ${daySlots().length} 个开放时段复制到所选日期，替换这些日期的原排班。已有预约保留，冲突时段自动跳过。</p><form onsubmit="copyWeek(event)">${weekDates.filter(d=>d!==date).map(d=>`<label class="copy-day"><input type="checkbox" name="days" value="${d}">${dateLabel(d)} ${weekNames[weekDates.indexOf(d)]}</label>`).join('')}<button class="bigbutton">复制到选中日期</button></form>`)}
function copyWeek(e){e.preventDefault();const days=new FormData(e.target).getAll('days');if(!days.length)return toast('请至少选择一天');const source=[...daySlots()],original=date;let skipped=0;for(const d of days){date=d;state.weekAvailability[d]=source.filter(t=>{if(coachSlotBusy(t)){skipped++;return false}return true})}date=original;save();closeModal();render();toast(`已复制到 ${days.length} 天${skipped?'，跳过 '+skipped+' 个冲突时段':''}`)}
function messages(){return `<h2 class="pagehead">消息中心</h2><div class="notice">以下为共用事件记录，用于展示双端通知流程。原型不发送微信消息。</div>${state.messages.map(m=>`<div class="card message"><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p><time>元素领域 Ez Element · 演示消息</time></div>`).join('')}`}
function members(){return `<h2 class="pagehead">人员管理</h2><input class="search" placeholder="搜索姓名或角色" aria-label="搜索人员" oninput="filterPeople(this.value)"><div id="people">${people('')}</div><div class="notice">陈晓是本原型的可交互学员；购课入账将记入陈晓账户。</div>`}
function people(q){return state.people.filter(p=>(p.name+p.type).includes(q)).map((p)=>`<div class="card member"><div class="avatar">${esc(p.name[0])}</div><div class="text"><b>${esc(p.name)} <span class="tag">${p.type}</span></b><small>${p.phone} · ${p.status}</small></div>${p.status==='待审核'?`<button class="pill" onclick="approve('${p.name}')">通过</button>`:p.name==='陈晓'?'<button class="pill secondary" onclick="purchaseDialog()">入账</button>':''}</div>`).join('')||'<div class="empty">没有匹配人员</div>'}
function filterPeople(q){$('#people').innerHTML=people(q)}
function approve(name){state.people.find(p=>p.name===name).status='正常';save();render();toast('审核通过')}
function finance(){return `<div class="row"><h2 class="pagehead">课时账与收款</h2><button class="pill" onclick="purchaseDialog()">＋ 入账</button></div><div class="card"><small class="sub">线下收款记录 · 演示累计</small><h2>¥${state.revenue.toLocaleString()}</h2><p class="sub">此处是收款记录，不等同于消课收入。</p></div>${balance()}${heading('陈晓 · 课时变动',`<button class="link" onclick="exportLedger()">导出 CSV ↗</button>`)}${ledger()}`}
function purchaseDialog(){modal('线下购课入账',`<p class="sub">为学员陈晓登记已收到的线下款项。</p><form onsubmit="purchase(event)"><label>课包类型<select name="type"><option value="private">私教课包 · 林教练</option><option value="group">团课课包</option></select></label><label>增加课时<input name="count" type="number" value="10" min="1" max="100" required></label><label>实际收款金额（元）<input name="amount" type="number" value="2000" min="0" max="99999" step="0.01" required></label><label>收款方式<select name="method"><option>微信转账</option><option>现金</option><option>银行卡转账</option></select></label><label>凭据备注<input name="memo" maxlength="60" placeholder="如：10 月续课，线下已收款"></label><button class="bigbutton" type="submit">确认入账并增加课时</button></form>`)}
function purchase(e){e.preventDefault();let f=new FormData(e.target),n=Number(f.get('count')),a=Number(f.get('amount')),t=f.get('type');if(!Number.isInteger(n)||n<1||n>100||!Number.isFinite(a)||a<0||a>99999)return toast('请输入有效课时和金额');state.packages[t].available+=n;state.revenue=Math.round((state.revenue+a)*100)/100;state.ledger.unshift({title:label(t)+'课包 · 线下入账',detail:`${f.get('method')} ¥${a} · ${f.get('memo')||'管理员登记'}`,value:`+${n} 节`});notify('课包已到账',`${label(t)}课包增加 ${n} 节，可在课包页查看。`);save();closeModal();render();toast('入账成功，学员余额已更新')}
function scheduleDialog(){modal('新增团课场次',`<p class="sub">发布后，学员端可立即查看并预约。</p><form onsubmit="addSession(event)"><label>课程名称<input name="name" value="全身力量" maxlength="20" required></label><label>日期<select name="date">${[28,29,30,31].map(d=>`<option ${date.endsWith(d)?'selected':''}>2026-10-${d}</option>`).join('')}</select></label><div class="row"><label>开始时间<input name="start" type="time" value="16:00" required></label><label>结束时间<input name="end" type="time" value="17:00" required></label></div><label>教练<select name="coach"><option>林教练</option><option>苏教练</option></select></label><label>场地<select name="room"><option>A 团操室</option><option>B 瑜伽室</option></select></label><label>人数上限<input name="capacity" type="number" value="10" min="1" max="30" required></label><p id="formError" class="form-error"></p><button class="bigbutton">发布场次</button></form>`)}
function addSession(e){e.preventDefault();let f=new FormData(e.target),c={id:'session-'+Date.now(),name:f.get('name').trim(),date:f.get('date'),time:f.get('start'),end:f.get('end'),coach:f.get('coach'),room:f.get('room'),capacity:Number(f.get('capacity')),occupied:0,type:'group',icon:'练'};let error='';if(!c.name||c.time>=c.end||!Number.isInteger(c.capacity)||c.capacity<1||c.capacity>30)error='请检查名称、起止时间与人数上限。';if(state.courses.some(x=>!x.cancelled&&x.date===c.date&&(x.coach===c.coach||x.room===c.room)&&x.time<c.end&&x.end>c.time)||state.bookings.some(b=>active(b)&&b.type==='private'&&b.coach===c.coach&&b.date===c.date&&b.time<c.end&&b.end>c.time))error='教练或场地在该时间已有课程，请调整。';if(error){$('#formError').textContent=error;return}state.courses.push(c);date=c.date;notify('新增团课',`${c.name} · ${c.date} ${c.time}，欢迎预约。`);save();closeModal();go('schedule');toast('团课已发布')}
function stopDialog(id){let c=state.courses.find(x=>x.id===id);modal('取消团课场次',`<p class="sub">${esc(c.name)} · ${c.date} ${c.time}</p><div class="notice">门店停课，释放陈晓在此场次的冻结课时。初始背景名额仅用于演示。</div><button class="bigbutton" onclick="stopSession('${id}')">确认停课并释放课时</button>`)}
function stopSession(id){let c=state.courses.find(x=>x.id===id);c.cancelled=true;state.bookings.filter(b=>b.courseId===id&&active(b)).forEach(release);c.occupied=0;notify('课程取消',`${c.name}已取消，未消耗的预约课时已释放。`);save();closeModal();render();toast('场次已取消，冻结已释放')}
function exportLedger(){const csv='\ufeff'+[['事项','说明','变动'],...state.ledger.map(l=>[l.title,l.detail,l.value])].map(row=>row.map(x=>'"'+String(x).replace(/^[=+\-@]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='元素领域-演示课时流水.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('演示流水已导出')}
render();
